export function sliderCellSize(v) {
  cellSize = v
}
export function sliderSpeed(v) {
  speed = v
}
export function hsvPickerPalette(h, s, v) {
  ph = h
}
export function toggleSparkle(v) {
  sparkle = v
}
var cellSize = 1, speed = .4, ph = 0, sparkle = 1, t1 = 0
export var band = 0
export var shimmer = 0
export function beforeRender(delta) {
  t1 = time(.1 * speed)
  band = wave(t1)
  shimmer = band * .12
}
export function render2D(index, x, y) {
  hsv(x * cellSize + ph, 1 - y, y + shimmer)
}

export function render2D(index, x, y) {
  hsv(nosie(x), 1, y)
}

export function sliderHue(v) {
