}
export function toggleSparkle(v) {
  sparkle = v
}
var hue = .1, speed = .08, sparkle = 1
export function render(index) {
  hsv(hue + index / pixelCount, 1, 1)
}

export function sliderCellSize(v) {
  cellSize = v
}
export function sliderSpeed(v) {
  speed = v
}
var cellSize = 1, speed = .4
export function render2D(index, x, y) {
  hsv(x * cellSize, 1, y * speed + .3)
}
